/**
 * 从 chapters/ch01 独立题页 HTML 解析 #ct 与题面元数据，生成：
 * - assets/ch01-problems-bundle.js（供 index.html）
 * - scripts/ch01-problems-meta.generated.mjs（供 Node 工具如 fetch-solution-lines）
 *
 * 运行：npm run build:ch01
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { parse } from 'node-html-parser';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.join(__dirname, '..');
const manifestPath = path.join(__dirname, 'ch01-manifest.json');
const bundleOut = path.join(repoRoot, 'assets', 'ch01-problems-bundle.js');
const metaOut = path.join(__dirname, 'ch01-problems-meta.generated.mjs');

function readManifest() {
  const raw = fs.readFileSync(manifestPath, 'utf8');
  return JSON.parse(raw);
}

function extractCodeTableHtml(table) {
  const parts = [];
  for (const child of table.childNodes) {
    if (child.nodeType === 1 && String(child.tagName).toLowerCase() === 'tr') {
      parts.push(child.outerHTML);
    }
  }
  return parts.join('\n');
}

function validateLineNumbers(table, fileLabel) {
  const rows = table.querySelectorAll('tr');
  let expected = 1;
  for (const tr of rows) {
    const ln = tr.querySelector('td.ln');
    if (!ln) continue;
    const n = parseInt(ln.textContent.trim(), 10);
    if (Number.isNaN(n) || n !== expected) {
      console.warn(`[build-ch01] ${fileLabel}: td.ln expected ${expected}, got "${ln.textContent.trim()}"`);
    }
    expected++;
  }
}

function parseProblemPage(absPath, expectedNum) {
  const html = fs.readFileSync(absPath, 'utf8');
  const root = parse(html);
  const probLink = root.querySelector('a#probLink');
  const probNumEl = root.querySelector('#probNum');
  const probNameEl = root.querySelector('#probName');
  const table = root.querySelector('table#ct');

  if (!table) throw new Error(`No table#ct in ${absPath}`);
  if (!probLink || !probNumEl || !probNameEl) {
    throw new Error(`Missing prob title elements in ${absPath}`);
  }

  validateLineNumbers(table, path.relative(repoRoot, absPath));

  let num = probNumEl.textContent.trim().replace(/\.$/, '');
  const name = probNameEl.textContent.trim();
  const url = probLink.getAttribute('href') || '';
  if (expectedNum && num !== expectedNum) {
    console.warn(`[build-ch01] ${absPath}: probNum "${num}" !== manifest num "${expectedNum}"`);
  }

  const codeTableHtml = extractCodeTableHtml(table);
  return { num, name, url, codeTableHtml };
}

function main() {
  const { problems } = readManifest();
  const meta = [];

  const items = problems.map((entry) => {
    const absPath = path.join(repoRoot, entry.path);
    if (!fs.existsSync(absPath)) {
      throw new Error(`Missing file: ${entry.path}`);
    }
    const p = parseProblemPage(absPath, entry.num);
    meta.push({ num: p.num, name: p.name, url: p.url });
    return p;
  });

  const payload = JSON.stringify(items);
  const bundleJs = `/** Generated by scripts/build-ch01-index-bundle.mjs — do not edit */
window.CH01_PROBLEMS = ${payload};
`;
  fs.writeFileSync(bundleOut, bundleJs, 'utf8');
  console.log(`Wrote ${bundleOut}`);

  const metaLines = meta.map(
    (m) =>
      `  { num: ${JSON.stringify(m.num)}, name: ${JSON.stringify(m.name)}, url: ${JSON.stringify(m.url)} }`
  );
  const metaMjs = `/** Generated by scripts/build-ch01-index-bundle.mjs — do not edit */
export const PROBLEMS_META = [
${metaLines.join(',\n')}
];
`;
  fs.writeFileSync(metaOut, metaMjs, 'utf8');
  console.log(`Wrote ${metaOut}`);
}

main();
